// Terminals.
func (q *SoftRecordQuery) Get() (*SoftRecordRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "one"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsSoftRecordDirect, scanSoftRecordDirect); used {
		if err != nil || len(direct) == 0 {
			return nil, err
		}
		return direct[0], nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil || len(rows.Data) == 0 {
		return nil, err
	}
	return scanSoftRecord(rows.Data[0], rows.Assemble, rows), nil
}

func (q *SoftRecordQuery) Gets() (*orm.Collection[SoftRecordRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsSoftRecordDirect, scanSoftRecordDirect); used {
		if err != nil {
			return nil, err
		}
		return collectSoftRecordDirect(direct, q.keyFn), nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	return collectSoftRecord(rows, q.keyFn), nil
}

// Stream visits independently owned rows without accumulating the complete result.
// Returning false stops the query and closes its database cursor.
func (q *SoftRecordQuery) Stream(visit func(*SoftRecordRow) bool) (orm.StreamResult, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.StreamResult{}, err
	}
	if visit == nil {
		return orm.StreamResult{}, &ir.Error{Code: orm.CodeIrInvalid, Msg: "stream visitor is required"}
	}
	q.q.Req.IR.Kind = "all"
	return orm.Stream(ctx, ex, q.q.Req, func(vals []any, rows *orm.Rows) bool {
		return visit(scanSoftRecord(vals, rows.Assemble, rows))
	})
}

// GetsBySeq applies seq = v and runs the collection terminal.
func (q *SoftRecordQuery) GetsBySeq(v int64) (*orm.Collection[SoftRecordRow], error) {
	return q.Seq(v).Gets()
}

